local ECSComponent = import("Frame.ECS.ECSComponent")

local httpModule = CS.Engine.Http.HttpModule
local MazeRoleDojo = import("Game.Dojo.MazeRoleDojo")
local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)

---@class MazeTeamComponent
local MazeTeamComponent = Class("MazeTeamComponent",ECSComponent)
--local base = ECSComponent

function MazeTeamComponent:__init()
    self.roles = nil     --所有的角色
    self.team = {}       --编队信息
    self.maxTeamRoles = 4   --队伍最大数量
    self.EventUpdateRoleAttr = Events.AddListener(Constants.EventNames.UICultivateMainRefreshCardData, Bind(self, self.UpdateRoleAttr))
end

function MazeTeamComponent:__delete()
    self.roles = nil     --所有的角色
    self.team = {}       --编队信息
    self.maxTeamRoles = 4   --队伍最大数量
    Events.RemoveListener(Constants.EventNames.UICultivateMainRefreshCardData, self.EventUpdateRoleAttr)
end

--[[
    @desc: 初始化角色数据
    author:{author}
    time:2020-04-21 12:10:58
    --@heroData: 
    @return:
]]
function MazeTeamComponent:InitRoles(roleData)
    if not roleData then return end

    self.roles = {}
    for k, v in pairs(roleData) do
        local role = MazeRoleDojo.New()
        role:Fill(v)
        if checkNumber(role.isAssistant) == Constants.MazeRole.CardHase then
            local cardDojo = cardComp:GetCardById(role.id)
            if cardDojo then 
                role.star = cardDojo.star
            end
        end
        self.roles[checkNumber(role.id)] = role
    end

    Events.Broadcast(Constants.EventNames.MazeHeroNumChange, nil)
end

--初始化编队数据
function MazeTeamComponent:InitTeam(teamData)
    if not teamData then return end
    self.team = {}

    for k, v in pairs(teamData) do
        table.insert(self.team, v.id)
    end

    --如果数量不够最大， 填满数组
    if #self.team < self.maxTeamRoles then
        for i = #self.team + 1, self.maxTeamRoles do
            self.team[i] = 0
        end
    end   
end

--更新一个角色的血量信息
function MazeTeamComponent:UndateRoleHp(jsondata)
    if not jsondata then
        return
    end

    for k, v in pairs(jsondata) do
        local role = self:GetRole(v.id)
        if role then
            role.hpPercent = checkNumber(v.healthPercent)
        end
    end
end

--更新一个角色的SP信息
function MazeTeamComponent:UpdateRoleSp(jsondata)
    if not jsondata then
        return
    end
    for k, v in pairs(jsondata) do
        local role = self:GetRole(v.id)
        if role then
            role.energy = checkNumber(v.sp)
        end
    end
end

function MazeTeamComponent:UpdateRoleAttr(id)
    if not id then
        return
    end
    local role = self:GetRole(checkNumber(id))

    if role then
        local cardData = cardComp:GetCardById(id)
        if cardData.star then
            role.star = checkNumber(cardData.star)
        end
        if cardData.cardLevel then
            role.cardLevel = checkNumber(cardData.cardLevel)
        end
    end
end

--复活一个角色
function MazeTeamComponent:RebornRole(jsondata)
    if not jsondata then
        return
    end

    for k, v in pairs(jsondata) do
        local role = self:GetRole(v.id)
        if role then
            --直接满血
            role.hpPercent = 1
        end
    end
end

--[[
    @desc: 增加一名助战角色
    author:{author}
    time:2020-04-14 20:08:53
    --@assistantRole: 
    @return:
]]
function MazeTeamComponent:AddAssistantRole(assistantRole)
    if not assistantRole then return end
    
    local role = MazeRoleDojo.New()
    role:Fill(assistantRole)

    --修正一次cardid（配表id） 服务器没传
    local mazeRoleVo = CfUtils.GetCfVo(AutoIds.IdSetting361, "MazeAssistRoleVo", role.id)
    if mazeRoleVo then
        role.cardId = mazeRoleVo.cardId
    end

    if not self.roles.id then
        self.roles[role.id] = role
        Events.Broadcast(Constants.EventNames.MazeHeroNumChange, nil)
    end
end

--获取一个卡牌信息，服务器数据
function MazeTeamComponent:GetRole(roleId)
    return self.roles[checkNumber(roleId)]
end

--获取一个卡牌信息，构造后的
function MazeTeamComponent:GetFakeRoleData(roleId)
    --取到数据后需要把 迷宫角色的血量和能量合并
    local role = self:GetRole(roleId)
    if not role then
        return nil
    end

    if role.isAssistant == 1 then 
        local assistRole = CfUtils.GetCfVo(AutoIds.IdSetting361, "MazeAssistRoleVo", roleId)
        table.merge(assistRole, role)
        return assistRole
    else
        local roleInfo = cardComp:GetCardById(roleId)
        table.merge(roleInfo, role)
        return roleInfo
    end
    return role
end

function MazeTeamComponent:CanUseRebornGoods()
    local canUse = false
    for k, v in pairs(self.roles) do
        if v.hpPercent <= 0 then
            return true
        end
    end
    return canUse
end

function MazeTeamComponent:CanUseCureGoods()
    local canUse = true
    for k, v in pairs(self.roles) do
        if v.hpPercent == 1 then--满血
            return false
        end
    end
    return canUse
end

--获取角色的数组
function MazeTeamComponent:GetRolesArr()
    local roleTab = {}
    for k, v in pairs(self.roles) do
        table.insert(roleTab, self:GetFakeRoleData(v.id))
    end
    return roleTab
end

return MazeTeamComponent